const { sequelize } = require('../models');

// N1: GL/JE numbers were generated by reading the highest existing number,
// sorted as a STRING (`ORDER BY gl_number DESC`), then parsing the trailing
// sequence and adding 1 — outside any lock. Two posts at once could read the
// same "highest so far" and get handed the same number (one dies on the
// unique constraint, or worse, both succeed if the constraint was ever
// missing). And a string sort breaks once a period passes 9999: "10000"
// sorts BEFORE "9999", so the next read finds "9999" again and everything
// from that point collides.
//
// This table holds one row per (clinic, doc type, period) — 'GL-202609',
// 'JE-202609', etc. Allocating the next number is a single
// `INSERT ... ON CONFLICT DO UPDATE ... RETURNING` inside the SAME
// transaction as the document it numbers (see DocumentNumberService.js):
// Postgres takes a row lock on the conflicting row as part of resolving the
// conflict, so a second transaction requesting a number for the same
// clinic+type+period blocks until the first commits or rolls back — no
// possible collision, no retry loop needed.
async function migrateDocumentNumberCounters(db = sequelize) {
  console.log('\n=== Document Number Counters Migration ===\n');

  await db.query(`
    CREATE TABLE IF NOT EXISTS document_number_counters (
      clinic_id INTEGER NOT NULL,
      doc_type VARCHAR(20) NOT NULL,
      period VARCHAR(10) NOT NULL,
      last_number INTEGER NOT NULL DEFAULT 0,
      updated_at TIMESTAMPTZ DEFAULT NOW(),
      PRIMARY KEY (clinic_id, doc_type, period)
    )
  `);

  // Seed each (clinic, doc_type, period) that already has GL/JE numbers from
  // the highest NUMERIC sequence actually in use (not the highest by string
  // sort — a period already past 9999 needs the real max, not whatever
  // "9999" or "10000" happens to look like alphabetically). Idempotent:
  // ON CONFLICT DO NOTHING, so re-running this after real numbers have
  // already been allocated through the new path never rewinds the counter.
  for (const [table, column, docType] of [
    ['general_ledger', 'gl_number', 'GL'],
    ['journal_entries', 'je_number', 'JE'],
  ]) {
    const [existing] = await db.query(
      `SELECT COUNT(*)::int AS cnt FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = :table`,
      { replacements: { table } }
    );
    if (!existing[0].cnt) continue;

    const [rows] = await db.query(`
      SELECT clinic_id, (m)[1] AS period, MAX((m)[2]::int) AS max_seq
      FROM (
        SELECT clinic_id, regexp_match(${column}, '^[A-Z]+-(\\d{6})-(\\d+)$') AS m
        FROM ${table}
      ) matched
      WHERE m IS NOT NULL
      GROUP BY clinic_id, period
    `);
    for (const row of rows) {
      if (!row.period || !row.max_seq) continue;
      try {
        await db.query(
          `INSERT INTO document_number_counters (clinic_id, doc_type, period, last_number)
           VALUES (:clinicId, :docType, :period, :lastNumber)
           ON CONFLICT (clinic_id, doc_type, period) DO NOTHING`,
          { replacements: { clinicId: row.clinic_id, docType, period: row.period, lastNumber: row.max_seq } }
        );
      } catch (err) {
        console.error(`Could not seed counter for ${docType} clinic ${row.clinic_id} period ${row.period}:`, err.message);
      }
    }
    console.log(`  ✅ Seeded ${docType} counters from ${table} (${rows.length} clinic/period rows)`);
  }

  console.log('  ✅ document_number_counters ready');
  console.log('\n=== Document Number Counters Migration Complete ===\n');
}

module.exports = { migrateDocumentNumberCounters };
